{
  "items": [
    {
      "slot": 1,
      "description": "Match a semantic version number consisting of three dot-separated non-negative integers without leading zeros, optionally followed by a hyphen and a dot-separated pre-release identifier made of letters, digits, and hyphens, and optionally followed by a plus sign and a dot-separated build identifier made of letters, digits, and hyphens.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$/"
    },
    {
      "slot": 2,
      "description": "Our release dashboard needs to validate calendar version tags like 2024.06. The format is a four-digit year, a dot, and a two-digit month from 01 to 12.",
      "regex": "/^\\d{4}\\.(0[1-9]|1[0-2])$/"
    },
    {
      "slot": 3,
      "description": "We need to validate semantic version strings before storing them. Our tooling is strict: no leading zeros in any numeric part, including pre-release numbers. Build metadata is allowed but ignored.",
      "regex": "/^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-(?:0|[1-9]\\d*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*)(?:\\.(?:0|[1-9]\\d*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*))*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$/"
    },
    {
      "slot": 4,
      "description": "python version specifiers operator then two or three dot separated numbers optional a b rc prerelease",
      "regex": "/^(?:~=|==|!=|<=|>=|<|>)\\d+\\.\\d+(?:\\.\\d+)?(?:(?:a|b|rc)\\d+)?$/"
    },
    {
      "slot": 5,
      "description": "The string must be a Python version specifier consisting of an operator followed by a version number. The operator is one of ==, >=, <=. The version number is exactly two dot-separated non-negative integers. No other characters are allowed.",
      "regex": "/^(?:==|>=|<=)\\d+\\.\\d+$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A French mobile number starts with 06 or 07, or with +33 followed immediately by 6 or 7. The remaining eight digits may be grouped into pairs separated by single spaces, dots, or hyphens, provided the same separator is used for every pair.",
      "regex": "/^(?:0[67]|\\+33[67])(?:\\d{8}|\\d{2}([ .-])\\d{2}\\1\\d{2}\\1\\d{2})$/"
    },
    {
      "slot": 2,
      "description": "french mobile starting 06 or 07 exactly ten digits no spaces",
      "regex": "/^0[67]\\d{8}$/"
    },
    {
      "slot": 3,
      "description": "Our signup form's phone field must accept any French phone number, so users can enter ten digits beginning with zero, with single spaces optionally separating the pairs of digits.",
      "regex": "/^0\\d(?: ?\\d{2}){4}$/"
    },
    {
      "slot": 4,
      "description": "french mobiles written as +33 then 6 or 7 then eight digits",
      "regex": "/^\\+33[67]\\d{8}$/"
    },
    {
      "slot": 5,
      "description": "An E.164 international number starts with a plus sign and contains between eight and fifteen digits in total; the first digit after the plus cannot be zero. Single spaces or hyphens may separate any of the digits, but the number must not start or end with a separator.",
      "regex": "/^\\+[1-9](?:[ -]?\\d){7,14}$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "The string must be a decimal integer between 0 and 255 inclusive. Leading zeros are not allowed, except for the number 0 itself. No other characters, signs, or spaces are permitted.",
      "regex": "/^(25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])$/"
    },
    {
      "slot": 2,
      "description": "A valid string is a number in scientific notation: an optionally signed significand, which is either an integer or a decimal with at least one digit before and after the decimal point, followed by the letter 'e' or 'E' and an optionally signed integer exponent. Leading zeros are not allowed in the significand's integer part or in the exponent, except for a single zero.",
      "regex": "/^[+-]?(0|[1-9][0-9]*)(\\.[0-9]+)?[eE][+-]?(0|[1-9][0-9]*)$/"
    },
    {
      "slot": 3,
      "description": "The string represents a signed decimal number. Rules:\n- An optional plus or minus sign may appear at the start.\n- The integer part must be one or more digits, with no leading zeros unless the integer part is exactly '0'.\n- An optional fractional part may follow, consisting of a decimal point followed by one or more digits.\n- No other characters are allowed.",
      "regex": "/^[+-]?(0|[1-9][0-9]*)(\\.[0-9]+)?$/"
    },
    {
      "slot": 4,
      "description": "In our network configuration tool, users must enter a single octet value for an IP address. The field should accept any integer from 0 to 255 inclusive; leading zeros are allowed, but no other characters or spaces are permitted.",
      "regex": "/^0*(25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])$/"
    },
    {
      "slot": 5,
      "description": "The string represents a signed decimal number. Rules:\n- An optional plus or minus sign may appear at the start.\n- The integer part must be a sequence of digits with no leading zeros, unless the integer part is exactly '0'.\n- An optional fractional part may follow, consisting of a decimal point followed by exactly two digits.\n- No other characters are allowed.",
      "regex": "/^[+-]?(0|[1-9][0-9]*)(\\.[0-9]{2})?$/"
    }
  ]
}

{
  "items": [
    {
      "slot": 1,
      "description": "A CSS length value: an optional minus sign, then a number (either an integer or a decimal with a dot and at least one fractional digit; a leading zero before the dot is optional), immediately followed by one of the units px, em, rem, or % (case-insensitive). No whitespace is allowed.",
      "regex": "/^-?(?:\\d+(?:\\.\\d+)?|\\.\\d+)(?:px|em|rem|%)$/i"
    },
    {
      "slot": 2,
      "description": "Our CMS needs to detect the opening tag of a div element in user-submitted HTML so it can inject a tracking attribute. The tag must start with <div followed by either whitespace or >. Attributes are allowed and may be quoted with single or double quotes; quoted values can contain any characters except the matching quote, including >. Unquoted attribute values cannot contain whitespace, quotes, =, <, >, or backticks. Self-closing tags (ending with />) must not be matched. Tag name and attribute names are case-insensitive.",
      "regex": "/^<div(?:\\s+[a-zA-Z_:][-\\w:.]*(?:\\s*=\\s*(?:\"[^\"]*\"|'[^']*'|[^\\s\"'=<>`]+))?)*\\s*>$/i"
    },
    {
      "slot": 3,
      "description": "A data URI for a base64-encoded image. It must start with data:image/, followed by a MIME subtype that is one of png, jpeg, jpg, gif, webp, or svg+xml (case-insensitive). Then a semicolon, the word base64, another semicolon, and a base64 payload. The payload consists of one or more characters from A–Z, a–z, 0–9, +, /, optionally followed by one or two = padding characters at the very end. No whitespace is allowed anywhere.",
      "regex": "/^data:image\\/(?:png|jpe?g|gif|webp|svg\\+xml);base64,[A-Za-z0-9+/]+={0,2}$/i"
    },
    {
      "slot": 4,
      "description": "Match a string that is a valid http or https URL. The host must be a valid domain name (labels of letters, digits, and hyphens, not starting or ending with a hyphen), and the optional port must be between 1 and 65535. The URL may have a path, query string, and fragment, which must not contain spaces.",
      "regex": "/^https?:\\/\\/(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?::(?:[1-9]\\d{0,3}|[1-5]\\d{4}|6[0-4]\\d{3}|65[0-4]\\d{2}|655[0-2]\\d|6553[0-5]))?(?:\\/[^\\s?#]*)?(?:\\?[^\\s#]*)?(?:#[^\\s]*)?$/i"
    },
    {
      "slot": 5,
      "description": "Our design system needs to validate spacing tokens that developers can use in our CSS-in-JS library. Tokens are lengths with an optional minus sign; the numeric part can be an integer or a decimal with at most two fractional digits, and a leading zero before the decimal point is optional. Allowed units are px, rem, em, vw, and vh. The value zero may be written without a unit, but any non-zero value must have a unit.",
      "regex": "/^(?:-?0(?:\\.0{1,2})?(?:px|rem|em|vw|vh)?|-?(?:[1-9]\\d*(?:\\.\\d{1,2})?|0\\.\\d{1,2}|\\.\\d{1,2})(?:px|rem|em|vw|vh))$/i"
    }
  ]
}

